package advprobe

import (
	"context"
	"fmt"
	"testing"
	"time"

	"github.com/prometheus/prometheus/promql"
	"github.com/prometheus/prometheus/promql/promqltest"
	"github.com/prometheus/prometheus/util/stats"
	"github.com/stretchr/testify/require"
)

func newEngine() *promql.Engine {
	return promql.NewEngine(promql.EngineOpts{
		Logger:                   nil,
		Reg:                      nil,
		MaxSamples:               1000000,
		Timeout:                  100 * time.Second,
		EnableAtModifier:         true,
		EnableNegativeOffset:     true,
		EnablePerStepStats:       true,
		NoStepSubqueryIntervalFn: func(int64) int64 { return durationMs(1 * time.Minute) },
	})
}

func durationMs(d time.Duration) int64 { return int64(d / (time.Millisecond / time.Nanosecond)) }

func run(t *testing.T, st promql.QueryEngine, storage interface {
	Querier(int64, int64) (q interface{}, err error)
}) {
}

func TestProbe(t *testing.T) {
	storage := promqltest.LoadedStorage(t, `
load 10s
  metricWith1SampleEvery10Seconds 1+1x100
  metricWith3SampleEvery10Seconds{a="1",b="1"} 1+1x100
  metricWith3SampleEvery10Seconds{a="2",b="2"} 1+1x100
  metricWith3SampleEvery10Seconds{a="3",b="2"} 1+1x100
`)
	t.Cleanup(func() { storage.Close() })

	cases := []struct {
		q                  string
		start, end         time.Time
		interval           time.Duration
	}{
		{`quantile_over_time(scalar(metricWith1SampleEvery10Seconds), metricWith3SampleEvery10Seconds[60s] @ 30)`, time.Unix(201, 0), time.Unix(220, 0), 5 * time.Second},
		{`max_over_time(metricWith3SampleEvery10Seconds[60s])`, time.Unix(201, 0), time.Unix(220, 0), 5 * time.Second},
		{`rate(metricWith1SampleEvery10Seconds[10s])`, time.Unix(201, 0), time.Unix(500, 0), 60 * time.Second},
	}
	for _, c := range cases {
		engine := newEngine()
		var qry promql.Query
		var err error
		if c.interval == 0 {
			qry, err = engine.NewInstantQuery(context.Background(), storage, nil, c.q, c.start)
		} else {
			qry, err = engine.NewRangeQuery(context.Background(), storage, nil, c.q, c.start, c.end, c.interval)
		}
		require.NoError(t, err)
		res := qry.Exec(context.Background())
		require.NoError(t, res.Err)
		s := qry.Stats()
		fmt.Printf("QUERY: %s\n  TotalSamples=%d SamplesRead=%d\n", c.q, s.Samples.TotalSamples, s.Samples.SamplesRead)
		fmt.Printf("  perStep total=%v\n", tsMap(s.Samples.TotalSamplesPerStepMap()))
		fmt.Printf("  perStep read =%v\n", tsMap(s.Samples.SamplesReadPerStepMap()))
	}
}

func tsMap(m *stats.TotalSamplesPerStep) string {
	if m == nil {
		return "<nil>"
	}
	return fmt.Sprintf("%v", *m)
}
EOF
go mod tidy >/dev/null 2>&1; go test -run TestProbe -v ./... 2>&1 | head -60

cat > /tmp/samplesread_probe/probe_test.go <<'EOF'
package probe

import (
	"context"
	"fmt"
	"runtime"
	"testing"
	"time"

	"github.com/prometheus/prometheus/promql"
	"github.com/prometheus/prometheus/promql/promqltest"
	"github.com/prometheus/prometheus/util/stats"
	"github.com/stretchr/testify/require"
)

const load = `
load 10s
  metricWith3SampleEvery10Seconds{a="1"} 1+1x100
  metricWith3SampleEvery10Seconds{a="2"} 1+1x100
  metricWith3SampleEvery10Seconds{a="3"} 1+1x100
  m1 1+1x100
`

func runQ(t *testing.T, perStep bool, q string, start, end time.Time, interval time.Duration) *stats.QuerySamples {
	st := promqltest.LoadedStorage(t, load)
	defer st.Close()
	eng := promqltest.NewTestEngine(t, perStep, 0, 1e9)
	ctx := context.Background()
	var qry promql.Query
	var err error
	opts := promql.NewPrometheusQueryOpts(perStep, 0)
	if interval == 0 {
		qry, err = eng.NewInstantQuery(ctx, st, opts, q, start)
	} else {
		qry, err = eng.NewRangeQuery(ctx, st, opts, q, start, end, interval)
	}
	require.NoError(t, err)
	r := qry.Exec(ctx)
	require.NoError(t, r.Err)
	return qry.Stats().Samples
}

// Finding 1: @ modifier reuse path zeroes TotalSamples for steps > 0
func TestF1_AtModifierTotalSamples(t *testing.T) {
	cases := []string{
		`predict_linear(metricWith3SampleEvery10Seconds[60s] @ end(), 3600)`,
		`predict_linear(metricWith3SampleEvery10Seconds[60s] @ 30, 3600)`,
		`max_over_time(metricWith3SampleEvery10Seconds[60s] @ 30)`, // step-invariant: control
	}
	for _, q := range cases {
		s := runQ(t, true, q, time.Unix(201, 0), time.Unix(220, 0), 5*time.Second)
		fmt.Printf("F1 %-70s TotalSamples=%-5d perStep=%v  SamplesRead=%d\n",
			q, s.TotalSamples, s.TotalSamplesPerStepMap(), s.SamplesRead)
	}
}

// Finding 2: SamplesRead double counted for subquery-as-range-vector-arg
func TestF2_SamplesReadDoubleCount(t *testing.T) {
	cases := []string{
		`max_over_time(m1[60s:5s])`,
		`max_over_time(max_over_time(m1[30s:10s])[60s:5s])`,
		`m1[60s:5s]`,
		`max_over_time(m1[60s])`,
	}
	for _, q := range cases {
		for _, ps := range []bool{false, true} {
			s := runQ(t, ps, q, time.Unix(201, 0), time.Time{}, 0)
			flag := ""
			if s.SamplesRead > s.TotalSamples {
				flag = "  <== SamplesRead > TotalSamples"
			}
			fmt.Printf("F2 perStep=%-5v %-52s TotalSamples=%-5d SamplesRead=%-5d%s\n", ps, q, s.TotalSamples, s.SamplesRead, flag)
		}
	}
}

// Finding 3: unbounded allocation from subquery-grid step array
func TestF3_Allocation(t *testing.T) {
	for _, q := range []string{
		`max_over_time(nonexistent_metric[10m:1ms])`,
		`max_over_time(nonexistent_metric[1h:1ms])`,
	} {
		var m0, m1r runtime.MemStats
		runtime.GC()
		runtime.ReadMemStats(&m0)
		t0 := time.Now()
		runQ(t, true, q, time.Unix(201, 0), time.Time{}, 0)
		d := time.Since(t0)
		runtime.ReadMemStats(&m1r)
		fmt.Printf("F3 %-46s allocated=%-14d bytes  elapsed=%v\n", q, m1r.TotalAlloc-m0.TotalAlloc, d)
	}
}
EOF
cd /tmp/samplesread_probe && GOFLAGS=-mod=mod go mod tidy >/dev/null 2>&1; go test -run 'TestF1|TestF2' -v ./... 2>&1 | grep -E '^(F1|F2|---|ok|FAIL|PASS)'
